  assert.deepEqual(solucao.processarFila(['a', 'b', 'c', 'd'], ['b', 'd']), [
    'a',
    'c',
  ]);
});

test('processarFila – nada entregue devolve a fila inteira', () => {
  assert.deepEqual(solucao.processarFila(['x', 'y'], []), ['x', 'y']);
});

